MAP
    NAME "SS_MAP_HIDRO_ZONAS_FEDERALES"
    INCLUDE "includes/globals.map"         
    WEB                                             
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'   
        END #METADATA
    END #WEB
        CONFIG "MS_ERRORFILE" "/srv/mapserver/err_zonas_federales.log"
    DEBUG 5 
    LAYER                                             
        NAME "SS_MAP_HIDRO_ZONAS_FEDERALES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS                       
        STATUS DEFAULT                                
        MINSCALE 1
        INCLUDE 'includes/conexion.map'                        
        DATA "gm_zona_federal from op.l_zonas_federales_cuerpos_agua using unique id_elemento_geografico using srid=32614"        
        TYPE LINE                                     
        LABELITEM "nb_zona"                         
            CLASS
                NAME "zonas federales validadas por la CONAGUA"       
                STYLE                                       
                    SYMBOL 0
                    COLOR 0 0 128                           
                    WIDTH 1.5                                 
                END #STYLE
                LABEL
                    ANGLE AUTO                        
                    SIZE 11
                    COLOR 0 0 0                       
                    OUTLINECOLOR 254 254 254            
                    TYPE TRUETYPE
                    FONT 'arial'                      
                END #LABEL
            END #CLASS 
            END #LABELITEM
    END #LAYER    
END #MAP